var n=`1430-jukjuk`;var o=`world-1430`;var a=`MH`;var i=`oceania`;var s=6;var u=62;var r={en:`Jukjuk`,ua:`Джукджук`};var d={en:`Jukjuk is described in Marshallese ethnobotanical sources as pounded cooked taro mixed with coconut; this uses that taro-based interpretation.`,ua:`Джукджук у маршалльських етноботанічних джерелах описують як розтерте варене таро з кокосом; тут використано саме цю версію.`};var c=[{en:`Peel store-bought edible taro, cut into large chunks and boil in plenty of water for 30–40 minutes until completely tender; drain.`,ua:`Очистіть куплене харчове таро, наріжте великими шматками й варіть у великій кількості води 30–40 хвилин до повної м’якості; відцідіть.`,t:[`boiling`,`draining`],m:40,i:[[`taro-root`,850,`g`],[`water`,1700,`ml`]]},{en:`Pound hot cooked taro until smooth and elastic, adding a tablespoon of warm water if needed.`,ua:`Потовчіть гаряче варене таро до гладкої еластичної маси, за потреби додайте ложку теплої води.`,t:[`pounding`],m:12,i:[[`water`,45,`ml`]]},{en:`Mix in desiccated coconut and coconut cream with a pinch of salt until the mass holds together.`,ua:`Умішайте кокосову стружку та кокосові вершки з дрібкою солі, доки маса не стане однорідною й триматиме форму.`,t:[`mixing`],m:6,i:[[`desiccated-coconut`,150,`g`],[`coconut-cream`,180,`ml`],[`sea-salt`,3,`g`]]},{en:`Shape into six small mounds and serve warm; dust with a little extra coconut if desired.`,ua:`Сформуйте шість невеликих порцій і подавайте теплими; за бажання посипте ще трохи кокосовою стружкою.`,t:[`garnishing`],m:4,i:[]}];var l={slug:n,id:o,country:`MH`,region:i,servings:6,minutes:62,title:r,text:d,steps:c};export{a as country,l as default,o as id,u as minutes,i as region,s as servings,n as slug,c as steps,d as text,r as title};